import React from 'react';
import { Meta, Story } from '@storybook/react';
import { Breadcrumb } from '../..';

const { Item } = Breadcrumb;

export default {
  title: 'Navigation/Breadcrumb/Item',
  component: Item,
  argTypes: {
    isCurrentPage: {
      table: {
        type: {
          summary: 'boolean',
        },
        defaultValue: {
          summary: 'false',
        },
      },
      control: {
        type: 'boolean',
      },
      description: 'To be used on the last item of the breadcrumb, which is not a link',
    },
    asChild: {
      table: {
        type: {
          summary: 'boolean',
        },
        defaultValue: {
          summary: 'false',
        },
      },
      control: {
        type: 'boolean',
      },
      description:
        'When `true` allows you to send a component as a Child. Can be useful to send an anchor tag with more props than just href or a `<Link/>` from ReactRouter. This will be ignored when `isCurrentPage = true`',
    },
    href: {
      table: {
        type: {
          summary: 'string',
        },
      },
      control: {
        type: 'text',
      },
      description: 'This will be ignored when `asChild = true` or `isCurrentPage = true`',
    },
    children: {
      table: {
        type: {
          summary: 'ReactNode',
        },
      },
      description: 'Content to be rendered. It can be just a string or an element',
    },
  },
  parameters: {
    docs: {
      description: {
        component: 'Item to be listed in the `Breadcrumb.Root` component',
      },
    },
  },
} as Meta;

export const DefaultItem: Story = (args) => (
  <Breadcrumb.Root>
    <Item
      href="/?path=/docs/admin-portal-shared-components-breadcrumb-Item--default-breadcrumb-item"
      {...args}
    >
      Page Name
    </Item>
  </Breadcrumb.Root>
);

export const WithIsCurrentPage: Story = () => (
  <Breadcrumb.Root>
    <Item isCurrentPage>Current Page</Item>
  </Breadcrumb.Root>
);

export const WithIsCurrentPageAndAsChild: Story = () => (
  <Breadcrumb.Root>
    <Item isCurrentPage asChild>
      <a
        href="/?path=/docs/admin-portal-shared-components-breadcrumb-Item--default-breadcrumb-item"
        onClick={() => alert('User clicked')}
      >
        Current Page
      </a>
    </Item>
  </Breadcrumb.Root>
);

export const WithAsChild: Story = () => (
  <Breadcrumb.Root>
    <Item asChild>
      <a
        href="/?path=/docs/admin-portal-shared-components-breadcrumb-Item--default-breadcrumb-item"
        onClick={() => alert('User clicked')}
      >
        Page Name
      </a>
    </Item>
  </Breadcrumb.Root>
);
